import argparse
import csv
import json

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = json.loads(parser.parse_args().payload)
    # args is ignored

    customers_west = set()
    with open("/inputs/customers.csv", newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            if row["region"].strip() == "west":
                customers_west.add(row["customer_id"])

    total = 0.0
    with open("/inputs/orders.csv", newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            if row["customer_id"] in customers_west:
                total += float(row["amount"])

    if total.is_integer():
        print(int(total))
    else:
        print(total)

if __name__ == "__main__":
    main()

import argparse
import json

parser = argparse.ArgumentParser()
parser.add_argument("payload")
args = parser.parse_args()
# Not using the payload, but we parse it

try:
    client_payload = json.loads(args.payload)
except:
    client_payload = {}

user_best = {}
with open("/inputs/events2.jsonl") as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        obj = json.loads(line)
        user = obj["user"]
        action = obj["action"]
        ts = obj["ts"]
        if user not in user_best:
            user_best[user] = (ts, action)
        else:
            max_ts, _ = user_best[user]
            if ts > max_ts:
                user_best[user] = (ts, action)
            # on tie (ts == max_ts) keep earlier

count = sum(1 for _, action in user_best.values() if action == "logout")
print(count)

import argparse
import csv
import datetime
import json


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('payload')
    args = parser.parse_args()
    payload = json.loads(args.payload)
    path = payload['path']

    with open(path, newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        if not reader.fieldnames:
            print(0)
            return

        date_col = None
        for name in reader.fieldnames:
            lower = name.lower()
            if lower == 'date' or 'date' in lower:
                date_col = name
                break

        if date_col is None:
            if len(reader.fieldnames) == 1:
                date_col = reader.fieldnames[0]
            else:
                print(0)
                return

        dates = []
        for row in reader:
            val = (row or {}).get(date_col, '')
            if val is None:
                continue
            val = str(val).strip()
            if not val:
                continue
            try:
                dates.append(datetime.date.fromisoformat(val))
            except ValueError:
                continue

        if not dates:
            print(0)
        else:
            print((max(dates) - min(dates)).days)


if __name__ == '__main__':
    main()
